head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10800";
scwin.std_cd_apct_tp_cd = null;
scwin.reg_button = null;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — stdCdApctTpCdList

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "rd_stdCdApctTpCd", fn: function(){ return (!(String(((dma_pageContext.get("stdCdApctTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("stdCdApctTpCdList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_datefmt_cal_stripIsuDd
 * @description 초기화 — datefmt cal strip Isu Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_stripIsuDd = function () { $c.date.checkCalendarFormat("cal_stripIsuDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        if ($c.util.getComponent('ipt_ldCheck').getValue() === "N") {
            fn_tgtBndStdCd(eval('document.JLDINF10800'));
        }
        if (($c.util.getComponent('ipt_objIsuCd').getValue() == null ? '' : String($c.util.getComponent('ipt_objIsuCd').getValue())) !== '') {
            $c.util.getComponent("ipt_coupnRt").focus();
        }
        $c.num.numberToKor("null", 'v_exp_isu_amt_money');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10800.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 3개다(stript#striptbndpop vs stript#striptregform vs stript#stripprocess) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":2
        ,"mmenu":8
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf10800' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.std_cd_apct_tp_cd = $c.util.getComponent('std_cd_apct_tp_cd');
        scwin.reg_button = $c.util.getComponent('reg_button');
        scwin.init_conds();
        scwin.init_datefmt_cal_stripIsuDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10800.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
