///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name openBnd
 * @description open Bnd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openBnd = async function () {
    if (($c.util.getComponent('ipt_objIsuCd').getValue() == null ? '' : String($c.util.getComponent('ipt_objIsuCd').getValue())) === '') {
        await $c.win.alert("대상채권(원본채권)를 선택해 주십시오.");
        $c.util.getComponent("ipt_objIsuCd").focus();
        return;
    }
    const fm = (document.JLDINF10800 || { elements: [] });
    let _popupWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _popupWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/stdcd/stript.do?method=striptBndPop", unresolved: "nav:" + "/stdcd/stript.do?method=striptBndPop" }; })();
    fm.action = '/stdcd/stript.do?method=striptBndPop';

};

/**
 * @method
 * @name setPrnpIsuNm
 * @description set Prnp Isu Nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setPrnpIsuNm = async function (fm) {
    if ($c.str.getByteLength($c.util.getComponent('ipt_objIsuCd').getValue()) === 0) {
        $c.util.getComponent('ipt_coupnRt').setValue("");
        await $c.win.alert("대상채권(원본채권)를 선택해 주십시오.");
        $c.util.getComponent("ipt_objIsuCd").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) > 0 && $c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) !== 6) {
        await $c.win.alert("원금분리채권 표면이자율 입력시\n입력예에 따라 소수점 포함해서 6자리[예:09.100]로 입력바랍니다.");
        $c.util.getComponent("ipt_coupnRt").focus();
        return;
    }
    if ($c.num.isNumber($('#ipt_coupnRt')[0])) {
        if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRt').getValue()) !== 0) {
            const int_rt = Del_Point2($('#ipt_coupnRt')[0]);
            let rdmp_dt = $c.util.getComponent('ipt_efTgtRdmpDt').getValue();
            rdmp_dt = rdmp_dt.substring(2, 6);
            $c.util.getComponent('ipt_isuNm').setValue('국고채원금 ' + int_rt + '-' + rdmp_dt);
            $c.util.getComponent('ipt_isuEngNm').setValue('KTB PRINCIPAL STRIPS ' + int_rt + '-' + rdmp_dt);
        } else {
            $c.util.getComponent('ipt_isuNm').setValue('');
            $c.util.getComponent('ipt_isuEngNm').setValue('');
        }
    }
    scwin.makeFisn();
};

/**
 * @method
 * @name makeFisn
 * @description make Fisn 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeFisn = function () {
    $c.util.getComponent("ipt_comEngAbbrv").setValue(fn_cut_spacingWords($c.util.getComponent('ipt_comEngAbbrv').getValue(), 15));
    const thisForm = $('#JLDINF10800');
    let temp = "";
    temp += $c.util.getComponent('ipt_comEngAbbrv').getValue();
    temp += "/Disc STRIPS Prin";
    temp += " " + $c.str.replaceAll($c.util.getComponent('ipt_redmptDd').getValue(), "-", "");
    temp += " Sr";
    temp += " Gtd";
    $c.util.getComponent('ipt_fisnVal').setValue(fn_cut_spacingWords(temp, 35));
    $c.util.getComponent('ipt_fisnVal').setValue(($c.util.getComponent("ipt_fisnVal").getValue() || '').toUpperCase());
    $c.util.getComponent('ipt_fisnMakeYn').setValue("Y");
};

